update public.official_exam_questions set review_note=$q$P2: C→¬J. A afirmativa (¬C→J) é a inversa, não equivalente. Gabarito E confere.$q$, question_text=$q$Texto-base:
    P1: Se a fiscalização foi deficiente, as falhas construtivas não
    foram corrigidas.
    P2: Se as falhas construtivas foram corrigidas, os mutuários não
    tiveram prejuízos.
    P3: A fiscalização foi deficiente.
    C: Os mutuários tiveram prejuízos.
    Considerando um argumento formado pelas proposições
    precedentes, em que C é a conclusão, e P1 a P3 são as premissas,
    julgue os itens a seguir.

Item: A proposição P2 é equivalente a “Se as falhas construtivas não foram corrigidas, os mutuários tiveram prejuízos”.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Raciocínio Lógico$q$ and t.topic_order=1 and t.block_name not ilike '%Hist%' limit 1) where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=52 and content_status='under_review';
